mapper.select:
SELECT p.inv_code, p.inv_name, p.version, p.org_name, p.body_code, (SELECT COUNT(*) FROM bom_detail d WHERE d.parent_code = p.inv_code) AS child_count FROM bom_parent p
AND (p.inv_code LIKE CONCAT('%', #{keyword}, '%') OR p.inv_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.inv_code LIMIT #{limit} OFFSET #{offset}
